package main

import (
	"path/filepath"
	"reflect"
	"slices"
	"strings"
	"testing"
	"time"
)

// The fixture is written from the Daemon's own code by the launcher's
// TestContractFixture and regenerated by `nix run .#regen-goldens`. Reading it
// through the Dashboard's real decoders pins every name, field and constant the
// Dashboard mirrors, so a Daemon-side rename fails here once the fixture is
// regenerated.
const contractDir = "testdata/contract"

const (
	s0 = "2026-03-14T09:28:33Z" // slot 0's child_start, in the older generation
	s1 = "2026-03-14T09:28:39Z"
	rv = "0a1b2c3d4e5f"
	// rvSelf is the revision on the self-update status files.
	rvSelf = "9f8e7d6c5b4a"
)

var selfUpdatePhases = []string{selfUpdateBuilding, selfUpdateWaiting, selfUpdateRestarting, selfUpdateBlocked}

// touched records "Type.Field" for every struct field that is non-zero
// somewhere under v.
func touched(v reflect.Value, seen map[string]bool) {
	switch v.Kind() {
	case reflect.Pointer:
		if !v.IsNil() {
			touched(v.Elem(), seen)
		}
	case reflect.Slice:
		for i := range v.Len() {
			touched(v.Index(i), seen)
		}
	case reflect.Struct:
		for i := range v.NumField() {
			if !v.Field(i).IsZero() {
				seen[v.Type().Name()+"."+v.Type().Field(i).Name] = true
			}
			touched(v.Field(i), seen)
		}
	}
}

// requireAllTouched fails for each field of the types that no decoded value set.
func requireAllTouched(t *testing.T, seen map[string]bool, types ...reflect.Type) {
	t.Helper()
	for _, ty := range types {
		for i := range ty.NumField() {
			if name := ty.Name() + "." + ty.Field(i).Name; !seen[name] {
				t.Errorf("%s is zero everywhere in the fixture: the Daemon no longer writes it, or its JSON key changed", name)
			}
		}
	}
}

func contractServer(t *testing.T) *server {
	t.Helper()
	srv := newServer(contractDir, filepath.Join(contractDir, statusFileName))
	srv.now = func() time.Time { return testNow }
	srv.alive = func(int, string) bool { return true }
	return srv
}

func TestContractHistory(t *testing.T) {
	entries, err := readHistory(filepath.Join(contractDir, eventsFileName))
	if err != nil {
		t.Fatal(err)
	}
	issue := subject{Label: "#1234", issue: "1234"}
	want := []historyEntry{
		// The older generation (eventsFileName+rotatedSuffix).
		{Event: "child_start", Kind: "dispatch", Slot: "0", Started: s0},
		{Event: "box", Kind: "dispatch", Slot: "0", Subject: issue, Detail: "fix-pass-1", Started: s0},
		{Event: eventImageBuild, Kind: "dispatch", Slot: "0", Detail: "started", Started: s0},
		// The current generation.
		{Event: eventImageBuild, Kind: "dispatch", Slot: "0", Detail: "finished", Started: s0},
		{Event: "settled", Kind: "dispatch", Slot: "0", Subject: issue, Started: s0, Outcome: "complete",
			Note: "landed green", PRURL: "https://github.com/acme/widgets/pull/77"},
		{Event: "child_start", Kind: "butler", Slot: "1", Started: s1},
		{Event: "box", Kind: "butler", Slot: "1", Subject: subject{Label: "docs-drift"}, Detail: "initial", Started: s1},
		{Event: "child_inherited", Kind: "butler", Slot: "1", Subject: subject{Label: "docs-drift"}, Started: s1},
		{Event: "backoff", Kind: "dispatch", Slot: "0", Detail: "5m0s child exited 1", Started: s0},
		{Event: "breaker_trip", Kind: "dispatch", Slot: "0", Detail: "3 failures 1h0m0s", Started: s0},
		{Event: "jam", Kind: "dispatch", Slot: "0", Started: s0,
			Detail: "30m0s no work is dispatchable and no sibling slot is doing anything that could unblock it"},
		{Event: "self_update", Detail: "built " + rv},
		{Event: "self_update", Detail: "handoff " + rv},
		{Event: "halt", Kind: "dispatch",
			Detail: "self-changed: daemon build /nix/store/aaaa-spindrift-daemon changed at tip " + rv},
	}
	for i := range entries {
		entries[i].Time = ""
	}
	covered := map[string]bool{}
	for _, w := range want {
		covered[w.Event] = true
		if !slices.ContainsFunc(entries, func(e historyEntry) bool { return reflect.DeepEqual(e, w) }) {
			t.Errorf("no history entry equals %+v", w)
		}
	}
	for name := range timeline {
		if !covered[name] {
			t.Errorf("the fixture has no timeline row for %q", name)
		}
	}
}

func TestContractDispatch(t *testing.T) {
	srv := contractServer(t)
	d, ok := srv.findDispatch(0, s0, 0)
	if !ok {
		t.Fatal("slot 0's Dispatch not found by its child_start time")
	}
	if d.Kind != "dispatch" || d.ChildLog != ".git/spindrift/child-0.log" || d.Rev != rv ||
		d.Phase != "fix-pass-1" || d.Outcome != "complete" || d.Note != "landed green" ||
		d.PRURL != "https://github.com/acme/widgets/pull/77" || !d.Closed ||
		d.Exit == nil || *d.Exit != 0 {
		t.Errorf("slot 0 dispatch = %+v", d)
	}
	if want := []passLog{{"fix-pass-1", ".git/spindrift/pass-1234.log"}}; !reflect.DeepEqual(d.PassLogs, want) {
		t.Errorf("PassLogs = %v, want %v", d.PassLogs, want)
	}
	if len(d.Subject) != 1 || d.Subject[0].Label != "#1234" {
		t.Errorf("Subject = %v", d.Subject)
	}

	d, ok = srv.findDispatch(1, s1, 0)
	if !ok {
		t.Fatal("slot 1's Dispatch not found")
	}
	if want := []passLog{{"initial", ".git/spindrift/pass-docs-drift.log"}}; !reflect.DeepEqual(d.PassLogs, want) ||
		d.Phase != "initial" || d.Closed || len(d.Subject) != 1 || d.Subject[0].Label != "docs-drift" {
		t.Errorf("slot 1 dispatch = %+v", d)
	}
}

func TestContractEventFields(t *testing.T) {
	seen := map[string]bool{}
	scanGenerations(filepath.Join(contractDir, eventsFileName), func(ev Event) {
		touched(reflect.ValueOf(ev), seen)
	})
	requireAllTouched(t, seen, reflect.TypeFor[Event]())
}

func TestContractStatus(t *testing.T) {
	st, raw, err := readStatus(filepath.Join(contractDir, statusFileName))
	if err != nil || st == nil {
		t.Fatalf("readStatus = %v, %v", st, err)
	}
	if !st.halted() || st.SelfUpdate == nil || st.SelfUpdate.Phase != selfUpdateBuilt ||
		!strings.HasPrefix(st.Reason, haltReasonSelfChanged+":") {
		t.Errorf("status = %+v", st)
	}
	v := contractServer(t).viewFrom(st, raw, nil)
	if !v.Halted || !v.SelfDrain || len(v.Kinds) != 3 || len(v.Slots) != 3 {
		t.Fatalf("view = %+v", v)
	}
	// Jammed, a pending tip-move wait, and a timed wait that a tip move also ends.
	if k := v.Kinds[0]; !k.Jammed || k.OnTipMove || k.AlsoTipMove || k.JamUntil == "" || k.Ready != "5" || k.ReadyAtJam != "2" {
		t.Errorf("dispatch check = %+v", k)
	}
	if k := v.Kinds[1]; !k.OnTipMove || k.AlsoTipMove {
		t.Errorf("butler check = %+v", k)
	}
	if k := v.Kinds[2]; k.OnTipMove || !k.AlsoTipMove || k.NextDue == "" {
		t.Errorf("research check = %+v", k)
	}
	if s := v.Slots[0]; !s.CIWait || s.ChildStartN != 1 || s.ImageBuildElapsed == "" || s.PRURL == "" || s.CIRunURL == "" {
		t.Errorf("slot 0 view = %+v", s)
	}

	// Every field the Dashboard decodes is set by some fixture status.
	seen := map[string]bool{}
	touched(reflect.ValueOf(st), seen)
	for _, phase := range selfUpdatePhases {
		p, _, err := readStatus(filepath.Join(contractDir, "self-update", phase, statusFileName))
		if err != nil || p == nil {
			t.Fatalf("%s: %v, %v", phase, p, err)
		}
		touched(reflect.ValueOf(p), seen)
	}
	requireAllTouched(t, seen, reflect.TypeFor[Status](), reflect.TypeFor[SlotStatus](),
		reflect.TypeFor[KindCheck](), reflect.TypeFor[TrackerCheck](), reflect.TypeFor[SelfUpdate]())
}

func TestContractSelfUpdatePhases(t *testing.T) {
	for _, phase := range selfUpdatePhases {
		t.Run(phase, func(t *testing.T) {
			path := filepath.Join(contractDir, "self-update", phase, statusFileName)
			st, raw, err := readStatus(path)
			if err != nil || st == nil || st.SelfUpdate == nil {
				t.Fatalf("readStatus = %v, %v", st, err)
			}
			if st.SelfUpdate.Phase != phase {
				t.Fatalf("Phase = %q, want %q", st.SelfUpdate.Phase, phase)
			}
			v := contractServer(t).viewFrom(st, raw, nil)
			blocked := phase == selfUpdateBlocked
			if got := v.SelfUpdate != ""; got == blocked {
				t.Errorf("pill label %q for %s", v.SelfUpdate, phase)
			}
			if v.SelfBlocked != blocked || (blocked && (v.SelfBlockedReason == "" || v.SelfBlockedReason != st.SelfUpdate.Reason)) {
				t.Errorf("SelfBlocked = %v, reason %q", v.SelfBlocked, v.SelfBlockedReason)
			}
			if v.SelfUpdateRev != rvSelf || v.SelfUpdateElapsed == "" {
				t.Errorf("rev %q, elapsed %q", v.SelfUpdateRev, v.SelfUpdateElapsed)
			}
		})
	}
}
